"""C011 integration: combine material demand and line windows into a rolling plan."""


def combine(payload, left, right):
    """left = material demand {wo: {component: qty}}, right = line windows {wo: [[line,start,end],...]}."""
    run_id = payload.get("run_id")
    freeze = payload.get("freeze", 0)
    changeover = payload.get("changeover", 0)
    lines = payload.get("lines", [])
    orders = payload.get("orders", [])
    wip = payload.get("wip", [])
    substitutes = payload.get("substitutes", {})
    lots = payload.get("lots", [])

    order_by_id = {o["id"]: o for o in orders}
    demand = left  # {wo: {component: qty}}
    windows = right  # {wo: [[line,start,end],...]}

    # ---- lots indexed by material ----
    lots_by_material = {}
    for lot in lots:
        lots_by_material.setdefault(lot["material"], []).append(lot)

    # ---- wip per line ----
    wip_by_line = {}
    for w in wip:
        wip_by_line.setdefault(w["line"], []).append(w)

    # ---- candidate placements per order ----
    # Each order has a list of (line, start, end) placements.
    placements = {}
    for oid, triples in windows.items():
        placements[oid] = [(t[0], t[1], t[2]) for t in triples]

    # ---- optimization ----
    # Order of orders for the completion vector: (priority, due, id).
    order_list = sorted(orders, key=lambda o: (o["priority"], o["due"], o["id"]))
    order_ids = [o["id"] for o in order_list]
    n = len(order_ids)

    # Priority groups.
    priorities = sorted({o["priority"] for o in orders})

    # Feasibility of a set of selected orders with placements and allocations.
    # We search over all combinations. n <= 5, so 2^5 = 32 subsets; placements small.
    # For each subset, we need to check:
    #   1. line capacity: no overlap, changeover between adjacent tasks (incl wip).
    #   2. material feasibility: shared lots, expiry >= task end, status PASS.
    #   3. each order fully placed (one placement).
    # We want to maximize priority qty, then completion vector, then lexicographic
    # (id,line,start,end,alloc) list.

    # Precompute demand per order.
    def order_demand(oid):
        return demand.get(oid, {})

    # Enumerate subsets by priority completion counts.
    # We'll do a full search over subsets and pick best by the objective.

    best = None
    best_key = None

    # For each subset (bitmask), check feasibility and compute objective.
    for mask in range(1 << n):
        selected_ids = [order_ids[i] for i in range(n) if (mask >> i) & 1]
        # Quick priority qty check is part of objective; we still must check feasibility.

        # Try all placement combinations for selected orders.
        # placements[oid] is a list; enumerate product.
        import itertools

        placement_lists = [placements[oid] for oid in selected_ids]
        if any(len(pl) == 0 for pl in placement_lists):
            continue

        for combo in itertools.product(*placement_lists):
            # combo: tuple of (line,start,end) aligned with selected_ids.
            chosen = dict(zip(selected_ids, combo))

            # ---- line capacity check ----
            # Build per-line list of tasks: wip + selected orders.
            line_tasks = {}
            for w in wip:
                line_tasks.setdefault(w["line"], []).append(
                    (w["start"], w["end"], w["id"], True))
            for oid in selected_ids:
                line, start, end = chosen[oid]
                line_tasks.setdefault(line, []).append((start, end, oid, False))

            ok = True
            for line, tasks in line_tasks.items():
                tasks_sorted = sorted(tasks, key=lambda t: (t[0], t[1]))
                # wip must be first (they occupy first position). Check no overlap and changeover.
                prev_end = None
                for (s, e, tid, is_wip) in tasks_sorted:
                    if prev_end is not None:
                        if s < prev_end + changeover:
                            ok = False
                            break
                    prev_end = e
                if not ok:
                    break
            if not ok:
                continue

            # ---- material feasibility ----
            # Aggregate demand across selected orders per component.
            total_demand = {}
            for oid in selected_ids:
                for comp, qty in order_demand(oid).items():
                    total_demand[comp] = total_demand.get(comp, 0) + qty

            # For each component, available lots = substitutes[comp] (default [comp]).
            # A lot is usable if status PASS and expiry >= task end (the order's end).
            # But expiry must be >= the task end of the order consuming it.
            # Since demand is aggregated per component, we need per-order expiry constraint.
            # We'll do a per-order allocation with shared lot capacity.
            # Simpler: check feasibility via a flow/greedy with expiry per order.

            # Build per-order demand with end times.
            order_reqs = []
            for oid in selected_ids:
                line, start, end = chosen[oid]
                for comp, qty in order_demand(oid).items():
                    order_reqs.append((oid, comp, qty, end))

            # Sort requirements by end ascending (earlier due first) for greedy.
            order_reqs.sort(key=lambda r: (r[3], r[0], r[1]))

            # Remaining lot capacity.
            lot_cap = {}
            for lot in lots:
                lot_cap[lot["id"]] = lot["qty"]

            # For each component, list of usable lots (substitutes).
            def usable_lots(comp, end):
                subs = substitutes.get(comp, [comp])
                result = []
                for s in subs:
                    for lot in lots_by_material.get(s, []):
                        if lot["status"] == "PASS" and lot["expiry"] >= end:
                            result.append(lot)
                return result

            feasible = True
            for (oid, comp, qty, end) in order_reqs:
                need = qty
                for lot in usable_lots(comp, end):
                    if need <= 0:
                        break
                    take = min(need, lot_cap.get(lot["id"], 0))
                    if take > 0:
                        lot_cap[lot["id"]] -= take
                        need -= take
                if need > 0:
                    feasible = False
                    break

            if not feasible:
                continue

            # ---- compute allocation (for lexicographic tie-break) ----
            # Recompute allocation deterministically for this combo.
            # We need the actual alloc list: (component, lot, qty) sorted, positive.
            # Re-run greedy to record allocations.
            lot_cap2 = {}
            for lot in lots:
                lot_cap2[lot["id"]] = lot["qty"]
            alloc = []
            for (oid, comp, qty, end) in order_reqs:
                need = qty
                for lot in usable_lots(comp, end):
                    if need <= 0:
                        break
                    take = min(need, lot_cap2.get(lot["id"], 0))
                    if take > 0:
                        lot_cap2[lot["id"]] -= take
                        need -= take
                        alloc.append((comp, lot["id"], take))
            alloc.sort()

            # ---- objective ----
            # Priority qty vector.
            prio_qty = []
            for p in priorities:
                q = sum(order_by_id[oid]["qty"] for oid in selected_ids
                        if order_by_id[oid]["priority"] == p)
                prio_qty.append(q)

            # Completion vector (0/1 in order_list order).
            comp_vec = tuple(1 if oid in chosen else 0 for oid in order_ids)

            # Lexicographic (id,line,start,end,alloc) list sorted by id.
            id_list = []
            for oid in sorted(selected_ids):
                line, start, end = chosen[oid]
                id_list.append((oid, line, start, end, tuple(alloc_for_order(oid, alloc, order_reqs, chosen))))

            # Build the full key for comparison.
            key = (tuple(prio_qty), comp_vec, tuple(id_list))

            if best_key is None or key > best_key:
                best_key = key
                best = (selected_ids, chosen, alloc, order_reqs)

    if best is None:
        selected_ids, chosen, alloc, order_reqs = [], {}, [], []
    else:
        selected_ids, chosen, alloc, order_reqs = best

    # ---- build output ----
    selected = sorted(selected_ids)

    # ERP orders: wip + planned, sorted by wo.
    erp_orders = []
    for w in wip:
        erp_orders.append({
            "wo": w["id"],
            "run": run_id,
            "sku": w["sku"],
            "qty": w["qty"],
            "due": w["due"],
            "start": w["start"],
            "end": w["end"],
            "line": w["line"],
            "status": "WIP_CONT",
            "parent": None,
        })
    for oid in selected_ids:
        o = order_by_id[oid]
        line, start, end = chosen[oid]
        erp_orders.append({
            "wo": oid,
            "run": run_id,
            "sku": o["sku"],
            "qty": o["qty"],
            "due": o["due"],
            "start": start,
            "end": end,
            "line": line,
            "status": "PLANNED",
            "parent": oid,
        })
    erp_orders.sort(key=lambda x: x["wo"])

    # MES: per line, seq from 1, sorted by (start, wo).
    mes = []
    line_ids = sorted({w["line"] for w in wip} | {chosen[oid][0] for oid in selected_ids})
    for line in line_ids:
        tasks = []
        for w in wip:
            if w["line"] == line:
                tasks.append((w["start"], w["id"], w))
        for oid in selected_ids:
            l, s, e = chosen[oid]
            if l == line:
                tasks.append((s, oid, order_by_id[oid]))
        tasks.sort(key=lambda t: (t[0], t[1]))
        for seq, (s, wid, obj) in enumerate(tasks, start=1):
            if isinstance(obj, dict) and "line" in obj and obj.get("status") is None:
                # wip
                pass
            if wid in {w["id"] for w in wip}:
                w = next(w for w in wip if w["id"] == wid)
                mes.append({
                    "run": run_id,
                    "line": line,
                    "seq": seq,
                    "wo": wid,
                    "qty": w["qty"],
                    "start": w["start"],
                    "end": w["end"],
                    "status": "WIP_CONT",
                })
            else:
                o = order_by_id[wid]
                l, s, e = chosen[wid]
                mes.append({
                    "run": run_id,
                    "line": line,
                    "seq": seq,
                    "wo": wid,
                    "qty": o["qty"],
                    "start": s,
                    "end": e,
                    "status": "PLANNED",
