    # Recompute allocation per order deterministically.
    # We stored alloc as a flat list; need per-order mapping.
    # Rebuild per-order allocations from order_reqs and alloc.
    # Simpler: recompute allocation from scratch for selected orders.
    lot_cap3 = {}
