            if need <= 0:
                break
            take = min(need, lot_cap3.get(lot["id"], 0))
            if take > 0:
                lot_cap3[lot["id"]] -= take
                need -= take
                per_order_alloc.setdefault(oid, []).append((comp, lot["id"], take))

    wms_rows = []
    for oid in selected_ids:
